 */
static inline __must_check bool refcount_dec_and_test(refcount_t *r)
{
	return __refcount_dec_and_test(r, NULL);
}

static inline void __refcount_dec(refcount_t *r, int *oldp)
{
	int old = atomic_fetch_sub_release(1, &r->refs);

/* 학습 해설
 * 해제 검사 없는 dec·마지막 감소는 leak 경고
 * 단순 dec와 마지막 감소를 검사하는 API의 차이가 메모리 수명에 미치는 영향을 배웁니다.
 * __dec는 release로1을 빼고 oldp를 기록합니다. old<=1이면 DEC_LEAK 포화 경고입니다. 따라서 old1에서0으로 내린 뒤 정상 종료로 두는 API가 아니며 포화 누수 상태로 바꿉니다. 공개 dec는 마지막 해제가 아니라 마지막이 아님을 아는 반환 경로에 맞춥니다.
