/**
 * refcount_dec_not_one - decrement a refcount if it is not 1
 * @r: the refcount
 *
 * No atomic_t counterpart, it decrements unless the value is 1, in which case
 * it will return false.
 *
 * Was often done like: atomic_add_unless(&var, -1, 1)
 *
 * Return: true if the decrement operation was successful, false otherwise
 */
bool refcount_dec_not_one(refcount_t *r)
{
	unsigned int new, val = atomic_read(&r->refs);

	do {
		if (unlikely(val == REFCOUNT_SATURATED))
			return true;

/* 학습 해설
 * 1이 아닐 때 감소·0과 포화의 특별 반환
 * 마지막 참조는 보존하며 일반 참조만 반환하는 helper의 예외 경로를 배웁니다.
 * dec_not_one은 unsigned val을 읽고 SATURATED이면 값 변경 없이 true,1이면 false입니다. 다른 값은 new=val-1을 CAS release로 적용합니다. val0이면 new>val underflow 경고를 내고 true로 반환하되 이 경로는 값을0에서 포화로 설정하지 않습니다. true가 모든 상태의 실제 감소 성공을 뜻한다고 일반화하면 안 됩니다.
