static inline void refcount_inc(refcount_t *r)
{
	__refcount_inc(r, NULL);
}

/* 학습 해설
 * 큰 batch 참조와 bad range·일반 정수 API로 쓰지 않기
 * 하나씩 추적하는 참조에서 큰 묶음 변경이 포화 여유와 산술 규약에 미치는 영향을 배웁니다.
