 */
static inline s64 ktime_divns(const ktime_t kt, s64 div)
{
	/*
	 * Negative divisors could cause an inf loop,
	 * so bug out here.
	 */
	BUG_ON(div < 0);
	if (__builtin_constant_p(div) && !(div >> 32)) {
		s64 ns = kt;
		u64 tmp = ns < 0 ? -ns : ns;

		do_div(tmp, div);
		return ns < 0 ? -tmp : tmp;
	} else {
		return __ktime_divns(kt, div);
	}
}
#else /* BITS_PER_LONG < 64 */
static inline s64 ktime_divns(const ktime_t kt, s64 div)
{
	/*
	 * 32-bit implementation cannot handle negative divisors,
	 * so catch them on 64bit as well.
	 */
	WARN_ON(div < 0);
	return kt / div;

/* 학습 해설
 * 큰 divisor의 long32 축소·정밀도 손실 경계
 * 64비트 divisor를32비트로 줄이기 위해 둘 다 shift하는 방법과 근사 경계를 배웁니다.
 * __ktime_divns는 positive divisor가32비트에 들어갈 때까지 right shift하며 sft를 셉니다. 기간 크기 tmp도 같은 sft만큼 줄이고32비트 divisor로 do_div합니다. 낮은 비트를 버리므로 일반 정확한 kt/div와 경계에서 몫이 다를 수 있습니다. 예를 들어 divisor=2^32+1,kt=3*divisor-1은 축소 뒤3,원래 몫은2입니다.
 * 원본 long32 경로의 정밀도 정책을 이해하고 정밀한 나눗셈이 필요한 요구에 helper의 실제 경계를 검증합니다. positive divisor와 유효 arithmetic 문맥을 사용하며 큰 divisor에서 항상 exact division이라고 설명하지 않습니다.
 */
s64 __ktime_divns(const ktime_t kt, s64 div)
{
	int sft = 0;
	s64 dclc;
	u64 tmp;

	dclc = ktime_to_ns(kt);
	tmp = dclc < 0 ? -dclc : dclc;

	/* Make sure the divisor is less than 2^32: */
	while (div >> 32) {
		sft++;
		div >>= 1;
	}
	tmp >>= sft;
	do_div(tmp, (u32) div);
	return dclc < 0 ? -tmp : tmp;
}
EXPORT_SYMBOL_GPL(__ktime_divns);
